import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"VLAS: Vision-Language-Action Model With Speech Instructions For Customized Robot Manipulation","description":"","frontmatter":{"title":"VLAS: Vision-Language-Action Model With Speech Instructions For Customized Robot Manipulation","arxiv":"2502.13508","date":"2025-02-19","authors":"Wei Zhao, Pengxiang Ding, Min Zhang, Zhefei Gong, Shuanghao Bai, Han Zhao, Donglin Wang","categories":"cs.RO","topics":"语音指令, VLA, 个性化机器人操作","outline":[2,2]},"headers":[],"relativePath":"papers/2502.13508.md","filePath":"papers/2502.13508.md","lastUpdated":null}'),l={name:"papers/2502.13508.md"};function e(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="vlas-vision-language-action-model-with-speech-instructions-for-customized-robot-manipulation" tabindex="-1">VLAS: Vision-Language-Action Model With Speech Instructions For Customized Robot Manipulation <a class="header-anchor" href="#vlas-vision-language-action-model-with-speech-instructions-for-customized-robot-manipulation" aria-label="Permalink to &quot;VLAS: Vision-Language-Action Model With Speech Instructions For Customized Robot Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2502.13508" target="_blank" rel="noreferrer">2502.13508</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-02-19</td></tr><tr><td><strong>作者</strong></td><td>Wei Zhao, Pengxiang Ding, Min Zhang, Zhefei Gong, Shuanghao Bai, Han Zhao, Donglin Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把 Whisper 编码器直接接进 LLaVA 骨干，让 VLA 不经 ASR 转写就听懂语音指令，并用声纹检索个人知识来完成&quot;拿我的杯子&quot;这类需要个体信息的定制任务。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>ICLR 2025 接收论文。arXiv v1 提交于 2025-02-19，v2 于 2025-02-21 修订；abs 页给出的 HTML 入口是 v2，本解读基于 v2 全文。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 的输入模态几乎清一色是&quot;文本指令 + 视觉观测&quot;。但人对机器人下指令的最自然方式是说话，而说话里携带的信息比转写出来的文字多——身份、情绪、语调都在波形里，转写一遍就没了。</p><p>论文用一个具体场景把这个抽象问题钉住：<strong>&quot;请把我的杯子拿过来&quot;</strong>。这句话的文本形式是欠定的，桌上有好几个杯子，&quot;我的&quot;指向哪一个取决于说话人是谁。传统 VLA 拿到的是转写后的文本，无从判断；接一个 ASR 的 VLA 拿到的也是同一段文本，同样无从判断。这不是识别精度的问题，是信息在管线里被丢掉了。</p><p>作者由此提出两条动机：其一，级联管线（ASR + VLA）让系统更大更复杂，增加计算与内存开销；其二，转写过程丢失了语义之外的辅助信息（身份、情绪、语调），而日常人类指令往往非结构化，只有靠这些信息才能被正确理解。这两条动机在 §9 会被它们自己的实验部分推翻，值得先记住。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VLA 这一侧，RT-2 / RoboFlamingo / OpenVLA 都是从预训练 VLM 微调出来的，只处理文本与图像。已有工作探索过加入触觉、深度等额外模态。MUTEX 提供了统一的多模态任务指定策略，但作者认为它没有充分利用近期 VLM 的能力。总之，语音这条路在 VLA 里几乎空白。</p><p>VLM 这一侧，能直接吃原始语音的模型直到 GPT-4o、Gemini、VITA 出现才变多；ImageBind-LLM、Unified-IO 2 探索过把音频接进多模态 LLM，但不面向机器人控制。</p><p>所以缺口是清楚的：<strong>要么有语音理解但不产生动作，要么能产生动作但只吃文本</strong>。中间没有人做。作者的路线是从 LLaVA 出发补上语音支路，理由是 LLaVA 完全开源、可复现、性能好，且它的两阶段视觉指令微调范式可以照搬到语音上。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是那个杯子场景暴露出的信息瓶颈。一旦承认&quot;文本不足以承载指令的全部内容&quot;，下一个问题就是：缺的那部分信息该怎么进入模型？</p><p>最直接的想法是把原始语音喂给 LLM。但语音与文本、图像不在同一个表示空间里，需要一个对齐步骤——而 LLaVA 恰好已经示范过怎么做：先用一个 MLP 把编码器输出映射到语言空间，再全参微调让 LLM 学会用它。把视觉换成语音，这套流程原样成立，只是对齐任务从图像描述换成语音识别。这就是三阶段训练的前两阶段。</p><p>第三个问题更实际：即使模型听到了声纹，它也不知道&quot;这个声纹属于谁、这个人喜欢什么&quot;。这类个体知识是动态的、可增删的，塞进权重里不合适。RAG 的适用条件正好命中——<strong>用声纹当 key 去查外部数据库</strong>，把检索到的个人知识作为背景拼进上下文。声纹提取用现成的说话人识别模块，不需要从零训练。</p><p>最后是数据。传统的 VLM 微调数据与机器人数据都没有语音，所以必须自己造：把 LLaVA 对话数据的问题转成语音得到 SQA，把 CALVIN 的文本指令转成语音得到 CSI。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>指令的语义只是波形里的一部分；把语音直接编成 token 送进 LLM，模型就能同时看到&quot;说了什么&quot;和&quot;谁在说&quot;，再用声纹去外部数据库查这个人的偏好与所有物，&quot;我的杯子&quot;这种在文本层面欠定的指令就变得可解。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;请把我的杯子拿过来&quot;为例，完整链路是：</p><ul><li><strong>语音编码</strong>：波形经 STFT 转成 80 维梅尔谱，补齐到固定的 3000 帧送进 Whisper 编码器，输出 1500 个隐状态；沿时间维做 reduction factor 为 5 的 reshape，得到 300 个语音 token，再经 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 映射到语言空间。</li><li><strong>声纹检索</strong>：同一段原始语音送进预训练的说话人识别模块提取声纹，以声纹为 key 查外部数据库，取回该用户的所有物与偏好，经文本 tokenizer 变成 token。</li><li><strong>视觉编码</strong>：CALVIN 的两路视角图像拼接后过 CLIP ViT，再经 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 映射。三路 token 拼接后送进 Vicuna 骨干：</li></ul><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Emb</span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">O</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">concat</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord mathrm">Emb</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">))</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Tok</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathrm">RAG</span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">))</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord mathrm">Emb</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathbf">O</span><span class="mclose">))</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><ul><li><strong>动作输出</strong>：把连续动作离散成 256 个等宽 bin，复用 LLM 词表里出现频率最低的 256 个 token 作为动作 token；7 维动作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϕ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">]</span></span></span></span> 拼成字符串自回归生成，再反离散化成连续值。</li><li><strong>三阶段训练</strong>：Stage I 用 LibriSpeech-360 只训语音 MLP 做粗对齐；Stage II 用 SQA（185K 样本、1,152 种音色）+ LLaVA 的 VQA 数据 + LibriSpeech-100 全参微调（冻结图像与语音编码器），得到 VLAS-Base；Stage III 在 CSI（CALVIN 的 389 条文本指令 × 500 种音色 ≈ 194K 条语音）上做行为克隆，训练时随机把一半样本换成语音指令。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化很轻：式(1) 是三路 token 的拼接，式(2) 是动作的自回归分解</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathbf">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Emb</span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">O</span><span class="mclose">))</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∏</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">Emb</span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">O</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>真正值得算一笔的是<strong>上下文成本</strong>，因为它直接关系到论文动机中&quot;级联管线增加计算与内存开销&quot;这一条是否成立。Whisper 编码器无条件把输入补齐到 30 秒（3000 帧梅尔谱），输出 1500 个隐状态，即每帧 20 ms；经 reduction factor 5 后每个语音 token 覆盖 100 ms 音频，总数固定为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">speech</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">5</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">3000/2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">300</span></span></span></span></span></p><p>注意这个数与指令实际长度<strong>无关</strong>。CALVIN 的指令普遍在 2 秒量级，因此约 93% 的语音 token 编码的是补零静音。作为对照，同一条指令的文本形式在 LLaMA 词表下通常不足 15 个 token。</p><p><strong>可以推断</strong>：在 7B 骨干上，端到端语音方案为每条指令多付出约 300 个 token 的注意力与 KV cache 开销，而级联方案只需约 15 个；级联多出的是 Whisper 解码器的一次前向，其单 token 成本远低于 7B LLM。也就是说，动机里&quot;更简单、更省算力&quot;这条主张在本文自己的设计下并不明显成立，论文全文也没有给出任何参数量、显存或延迟的对比数字。真正站得住的动机只有第二条——信息丢失。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：加了语音支路会不会伤害原来的能力？</strong> 在 CALVIN ABCD→D 上，作者用同样配置微调 LLaVA 得到一个只吃文本的 VLA 作为基线。结果是 VLA（文本）平均序列长度 3.80，VLAS（文本）3.74，VLAS（合成语音）3.70，VLAS（10 人真实语音）3.61。两个级联基线是 RoboFlamingo + ASR 3.41 与 VLA + ASR 3.13。VLM 侧，VLAS-Base 在 VQAv2 / VizWiz / SQA-I / TextVQA / POPE / GQA 上与 LLaVA-1.5 基本持平（SQA-I 甚至 72.2 vs 66.8 更高）。所以结论是：<strong>加语音的代价很小，但不是零</strong>（文本档 3.74 &lt; 3.80）。</p><p><strong>问题二：端到端语音是否优于 ASR 级联？</strong> 表 1 的答案是明确的：VLAS 的 3.70 远高于 VLA+ASR 的 3.13。作者归因于&quot;我们在专门数据上微调过，识别机器人控制指令更准，而外部 ASR 对控制命令不敏感，误差被放大&quot;。这个解释有一处张力：同一个 Whisper large-v2 之下，RoboFlamingo+ASR 拿到 3.41，比 VLA+ASR 高 0.28，而 VLA 的文本档（3.80）本应强于 RoboFlamingo。也就是说，两个级联基线从文本退化到语音的幅度差别很大，论文没有解释。</p><p><strong>问题三：语音带来的个体信息值不值钱？</strong> 这是全文最重要的一组，也是最该细看的一组。自建的定制任务基准分三类（物主关系、用户偏好、复合任务，含两阶段），每类 39 种未见音色。结果是：</p><ul><li>VLA（文本）：平均 19.2%</li><li>VLAS（合成语音，带 RAG）：平均 86.5%</li><li>VLAS（真实语音，带 RAG）：平均 78.6%</li><li>VLAS 去掉 RAG：平均 <strong>16.0%</strong></li><li>VLA（文本）<strong>加上</strong> RAG：平均 <strong>82.0%</strong></li></ul><p>作者用前两行论证语音的价值，用后两行论证 RAG 的价值。但把四行放在一起读，结论是另一回事：去掉 RAG 后 VLAS（16.0%）与纯文本 VLA（19.2%）基本同档；而给纯文本 VLA 接上 RAG 就能到 82.0%，与完整 VLAS 的 86.5% 只差 4.5 点，在物主关系一项上 VLA+RAG 的 97.4% 甚至<strong>高于</strong> VLAS 的 94.7%。</p><p><strong>问题四：语音理解本身有没有损耗？</strong> LibriSpeech 上 VLAS-Base 的 WER 2.79%，与 Whisper large-v2 的 2.7% 基本持平。但在自建的 SGQA（把 GQA 的问题转成语音）上，VLAS-Base 得 50.8，而同一模型家族用真值文本的 LLaVA-1.5 是 62.0——<strong>下降 11.2 点</strong>。作者的解释是 reduction factor 造成的下采样损失。</p><p><strong>真机</strong>：用 Berkeley UR5 数据集加自采的取杯数据微调，只有一张成功案例图，<strong>没有任何数值</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：VLAS 是第一个不依赖外部 ASR、直接吃原始语音的 VLA，做法是把 Whisper 编码器接到 LLaVA 骨干上，用三阶段训练完成语音-文本对齐、多模态问答、机器人动作微调。它同时给出两个新数据集（SQA 与 CSI）和一个 Voice RAG 范式——用声纹当 key 检索个人知识，从而解&quot;拿我的杯子&quot;这类文本层面欠定的指令。在 CALVIN 上加语音的代价很小（3.80 → 3.74 文本档、3.70 合成语音档），在自建定制任务上从 19.2% 提到 86.5%。但同一张表显示，把 Voice RAG 直接接到纯文本 VLA 上就能拿到 82.0%，而去掉 RAG 的 VLAS 只剩 16.0%——绝大部分增益属于 RAG 而非端到端语音。语音理解本身也有可测的损耗：SGQA 上比用真值文本低 11.2 点。</p><p><strong>三句话版</strong>：把语音直接编进 VLA 的上下文，并用声纹检索个人知识来消解个性化指令的歧义。CALVIN 上代价很小、定制任务上提升巨大，但消融表明提升几乎全部来自检索模块。端到端语音相对&quot;ASR + 同样的检索模块&quot;的净增量约 4.5 个百分点。</p><p><strong>一句话版</strong>：让机器人听声音而不是听文字，并用声纹去查&quot;这个人是谁、他喜欢什么&quot;。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是论文的第二条动机本身：<strong>&quot;转写会丢失非语义信息，因此必须端到端整合语音&quot;</strong>。这个&quot;因此&quot;不成立，而反驳它的证据就在论文自己的表 2 里。</p><p>Voice RAG 的声纹并不是由 LLM 从语音 token 中&quot;读&quot;出来的——论文明确写了，声纹由一个<strong>独立的预训练说话人识别模块</strong>提取，然后以文本形式检索并拼进上下文。既然如此，这个模块同样可以挂在任何一个只吃文本的 VLA 前面：录音进去，一路走 ASR 得到指令文本，另一路走说话人识别得到声纹并检索。作者自己跑了这条路（<code>VLA + RAG</code> 一行），得到 82.0% 的平均成功率，与完整 VLAS 的 86.5% 相差 4.5 点，且在物主关系任务上反超。</p><p>也就是说，<strong>动机所指的信息丢失问题，是被一个可以自由拆装的旁路模块解决的，不是被端到端整合解决的</strong>。一旦承认这一点，端到端方案的价值就必须重新论证——它剩下的净收益是那 4.5 点，而代价是每条指令 300 个语音 token（§6）、SGQA 上 11.2 点的理解损耗，以及 CALVIN 文本档 0.06 的退化。论文没有讨论这个取舍，也没有给出任何延迟或显存数字来支撑&quot;更简单&quot;的说法。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只需要作者公开的 CSI 数据与 CALVIN 环境：</p><ol><li>取 CSI 的评测语音（39 种未见音色），用 Whisper large-v2 转写，报告两个数字：字错误率，以及<strong>转写结果精确落在 CALVIN 那 389 条规范指令集合中的比例</strong>。</li><li>构造一个&quot;吸附&quot;版级联：把 ASR 输出用编辑距离或句向量最近邻映射回 389 条规范指令之一，再送给文本 VLA。</li><li>在 ABCD→D 上评三档：VLA + 原始 ASR 文本、VLA + 吸附后文本、VLAS（语音）。</li><li>判据：若吸附后 VLA 的平均序列长度回升到 3.7 以上，则&quot;级联误差传播&quot;这条论证在闭集指令的 CALVIN 上基本不成立，表 1 中 3.70 vs 3.13 的差距应重述为实现细节而非范式差异；若吸附后仍显著低于 3.7，则说明退化来自别处（例如提示词格式或分词差异），同样需要说明。</li></ol><p>这个实验成本极低，却直接决定表 1 的主结论怎么解释。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出替代解释：<strong>表 1 中级联基线的劣势可能来自训练-推理的字符串失配，而不是信息丢失</strong>。CALVIN 的指令是一个只有 389 条的闭集，VLA 基线在训练时看到的是这些指令的精确字符串；Whisper 的输出在标点、大小写、数字写法、同音词上都可能与训练串不同（Whisper large-v2 在 LibriSpeech 上的 WER 只有 2.7%，很难解释 0.67 的平均序列长度损失）。而 VLAS 在 Stage III 恰好用同一批 TTS 音频与同一批指令做过微调，等于对评测分布做过适配。</p><p>设计能分辨的实验：给三个 arm 相同的输入音频——(a) VLAS；(b) VLA + Whisper 原始转写；(c) VLA + Whisper 转写 + 最近邻吸附到 389 条规范指令。若 (c) ≈ (a)，则端到端语音在闭集指令下没有实质优势，论文的范式主张需要限定到开放集指令场景。</p><p>第二条攻击线针对定制任务基准。三类任务的成功率里有多项是 100.0%，而每类只有 39 种音色；VLAS 与 VLA+RAG 的差距（86.5 vs 82.0）落在 39 个样本的量级下很可能不显著，论文没有报置信区间或显著性检验。一个直接的检验是把音色数扩到 300 以上并加入带口音、带背景噪声、带情绪的真实录音，看两条路线的差距是扩大还是消失——如果扩大，说明端到端确实在&quot;难语音&quot;上更稳；如果消失，则 §9 的判断成立。</p><p>第三条更针对方法本身：把说话人识别模块换成一个<strong>故意退化</strong>的版本（例如只用音高均值做 8 类粗分），同时给 VLAS 与 VLA+RAG 使用。如果两者同步崩塌，就坐实了&quot;个性化能力完全由声纹模块承载，与主干如何吃语音无关&quot;。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文把语音里的非语义信息压缩成一个<strong>静态的 key</strong>：声纹 → 数据库 → 一段固定的背景知识。这个 framing 把&quot;谁在说&quot;用满了，却把&quot;怎么说&quot;整个丢掉了——语调、语速、犹豫、重音这些在时间轴上变化的信号，在当前设计里既不进检索也不进动作。而它们恰恰承载着控制层面最有用的信息：紧迫程度、把握程度、是否在纠正机器人上一步的动作。</p><p>一个非增量的重构是把语音从&quot;指令的载体&quot;改成<strong>持续的控制信号</strong>：不是在动作开始前听一句话，而是在整个 rollout 期间持续接收音频流，让韵律直接调制策略的行为参数（速度、力度、是否暂停）。驱动它的具体局限是 §6 算出的那个数字——现在每条指令固定花 300 个 token 编码 30 秒窗口，其中 93% 是静音；这个预算如果用来编码执行期间的真实音频，信息密度会高得多。</p><p>可借鉴的相邻领域工具有两处：语音情感与韵律识别里的帧级特征（F0 轮廓、能量包络、说话速率），以及共享自治（shared autonomy）里把人类输入当作对策略分布的实时修正而非一次性目标。把两者结合，策略的条件就从&quot;一句话 + 一段个人知识&quot;变成&quot;一段话 + 一条持续的韵律轨迹&quot;。</p><p>第一个实验可以做得很小：在 CALVIN 上构造一组<strong>执行期干预</strong>样本——机器人开始动作后，人用&quot;停&quot;、&quot;慢一点&quot;、&quot;不是那个&quot;等短语打断，同时记录韵律特征。比较三种策略：(a) 忽略执行期音频；(b) 把打断语转写成文本重新下指令；(c) 直接把执行期音频流接进策略上下文。指标是从人开口到机器人行为改变的延迟、以及纠正后的任务完成率。如果 (c) 在延迟上显著优于 (b)，就说明端到端语音真正的价值不在&quot;听懂一句话&quot;，而在&quot;能持续听&quot;——这会把本文的贡献重新定位到一个论文自己没有主张的地方。</p>',61)])])}const u=a(l,[["render",e]]);export{g as __pageData,u as default};
